    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount && amount == 10 && c.pot() == 0);
        uint balBefore = address(this).balance;
        c.play{value: amount}();
        uint balAfter = address(this).balance;
        assert(balAfter == balBefore - 10 || balAfter == balBefore);
    }
    receive() external payable {}
}

