contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        require(address(this).balance >= 20);
        // first play: must send exactly 10 wei; c has no way to receive ether otherwise
        uint b0 = address(this).balance;
        c.play{value: 10}();
        uint pot1 = c.pot();
        uint b1 = address(this).balance;
        // second play (may revert if first play won and the second also wins)
        bool reverted;
        try c.play{value: 10}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (!reverted) {
            uint pot2 = c.pot();
            uint b2 = address(this).balance;
            assert(
                (pot2 == 0 && b2 == b1 + 9 && b1 == b0 - 10) ||
                (pot2 == 20 && b2 == b0 - 20 && b1 == b0 - 10)
            );
        } else {
            // revert only possible when pot was 0 and nothing changed
            assert(c.pot() == 0 && address(this).balance == b1);
        }
    }

    receive() external payable {}
}
